mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "trackingNumber": {
      "type": "string",
      "description": "Carrier tracking number, for example BD784512963IN."
    },
    "orderId": {
      "type": "string",
      "description": "Unique order identifier, for example ORD-1002.",
      "minLength": 1
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "sku": {
      "type": "string",
      "description": "Product SKU identifier, for example SKU-A100.",
      "minLength": 1
    }
  },
  "required": ["sku"],
  "additionalProperties": false
}
